import { BilingualText } from '../types';
import { ACTION_IMAGE_ALT, actionImage } from './italianGrammarPictures';
export type GrammarActivityType = 'correct' | 'order' | 'translate' | 'write';
export interface GrammarActivity {
  id: string; topicId: string; level: 'A1' | 'A2' | 'B1'; type: GrammarActivityType;
  // For 'correct'/'order' the source is Italian text (kept as a plain string).
  // For 'translate' it is the sentence to translate FROM, shown in the learner's
  // language, so it is a localized record.
  title: BilingualText; prompt: BilingualText; source?: BilingualText; words?: string[];
  acceptedAnswers?: string[]; modelAnswer: string; hint: BilingualText; explanation: BilingualText;
  // Optional picture (path relative to the app's base URL) and its alt text.
  image?: string; imageAlt?: BilingualText;
}

export const normaliseGrammarAnswer = (value: string): string => value
  .normalize('NFKC')
  .toLocaleLowerCase()
  .replace(/[’‘ʼ＇]/g, "'")
  .replace(/'\s+/g, "'")
  .replace(/[.!?]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

export const matchesGrammarAnswer = (response: string, acceptedAnswers: string[]): boolean =>
  acceptedAnswers.some(answer => normaliseGrammarAnswer(answer) === normaliseGrammarAnswer(response));
